  const generate = ()=>{if(reviewedFlow.choice.mode==='reviewed'){toast('已审资料模式请使用面板按钮生成，旧生成入口已停用。',true);return;}if(!allowProjectGeneration())return;if(reportDirty||favorableDraftDirty||candidate2Review.dirty){setPendingAction({title:'生成新的一组名字',action:()=>{if(!allowProjectGeneration())return;setFavorableDraft(null);performGenerate();}});return;}performGenerate();};
  const applyFavorableDraft=()=>{if(!allowManualUpdate()||!favorableDraftDirty||favorableDraft?.key!==favorableContextKey)return;commitPref('preferredElements',[...favorableSelection]);setFavorableDraft(null);toast('五行选择已应用到当前起名偏好；保存档案或重新生成后存入本机，旧方案依据保留。');};
  const captureReviewConflict=async(error:unknown,draft:NamingSession)=>{if(!isReviewConflict(error))return;const owner=navigationEpoch.current,api=getCatalogApi();try{const latest=await api.readSessionDetail(draft.id);if(latest?.id===draft.id&&appAlive.current&&owner===navigationEpoch.current&&getCatalogApi()===api&&sessionRef.current?.id===draft.id){rememberCanonical(latest);setReviewConflict({id:draft.id,latest,draft:structuredClone(draft)});}}catch{/* The save error still leaves the local draft available. */}};
  const persist = async (updated:NamingSession)=>{if(Object.hasOwn(updated,'candidate2Naming'))throw Error(candidate2ReadonlyReason);if(storageReadOnly)throw Error('旧版客户库当前只读，请先备份并迁移。');const revision=draftRevision.current;try{const canonical=await window.studio.saveSession(updated);if(sessionRef.current?.id===updated.id&&draftRevision.current===revision){setSession(canonical);setReviewConflict(null);}rememberCanonical(canonical);return canonical;}catch(error){await captureReviewConflict(error,updated);throw error;}};
