  const toggleFavorite = (c:NameCandidate)=>{if(candidate2Session){const draft=candidate2Review.draftCandidate(c.id);if(draft)candidate2Review.editCandidate(c.id,{favorite:!draft.favorite});return;}return updateCandidate(c.id,{favorite:!c.favorite});};
  const compare = (id:string)=>{setCompareIds(old=>{if(old.includes(id))return old.filter(x=>x!==id);if(old.length>=4){toast('最多同时比较 4 个名字。',true);return old;}return [...old,id];});};
  const exportReport = ()=>{if(candidate2Session){candidate2Report.request(boot?.desktop===true?'export':'preview');return;}if(busyRef.current)return;if(favorableDraftDirty){setPage('bazi');toast('请先应用或撤销五行草稿后再导出。',true);return;}if(!session){toast('先生成或选择一份方案。',true);return;}if(!sessionCurrent){toast('资料或偏好已改变，这份结果需要重新生成。也可明确打开原方案快照后导出历史报告。',true);return;}retireDetail();setExportError('');setExportPlan(structuredClone(session));};
