  const culturalContextKey=JSON.stringify([profile.id,session?.id??null,session?.reviewRevision??null,session?.reviewToken??null,formDraftKey(profile,prefs),draftRevision.current,projectUiEpoch.current,boot?.stats.dataVersion??null,boot?.storageState?.version??null]);
