    {visibleHistory&&session&&!visibleRestore&&<SessionHistory key={candidate2Session?'c2-history-'+candidate2History.state.listVersion:'ordinary-history'} revisions={visibleHistory} current={candidate2Session?savedSession??session:session} stale={!sessionCurrent||candidate2Session&&formDirty} busy={!!busy} restoreBlocked={candidate2Session?!candidate2History.state.canRestore:undefined} status={candidate2Session?<Candidate2HistoryStatus {...candidate2History.status}/>:undefined} subtitle={candidate2Session?'历史只读浏览；明确恢复仅改变人工文字、收藏和五行草案。有实际变化时产生新版本。':undefined} onClose={()=>{if(candidate2Session)candidate2History.close();else setHistory(null);}} onRestore={restoreRevision}/>}
